index 0000000..a1b2c3d
--- /dev/null
+++ b/src/sanitize-svg.js
@@ -0,0 +1,68 @@
+/**
+ * Sanitize an SVG string to prevent XSS attacks.
+ * Removes script elements, event handler attributes, and javascript: URLs.
+ * @param {string} svgString - The SVG string to sanitize
+ * @returns {string} The sanitized SVG string
+ */
+const sanitizeSvg = function (svgString) {
+    // Use DOMParser to safely parse the SVG without executing scripts
+    const parser = new DOMParser();
+    const doc = parser.parseFromString(svgString, 'image/svg+xml');
+
+    // Check for parse errors; if malformed, return original and let caller handle it
+    const parseError = doc.querySelector('parsererror');
+    if (parseError) {
+        return svgString;
+    }
+
+    // Remove all <script> elements
+    const scripts = doc.getElementsByTagName('script');
+    // Use a while loop since the NodeList is live and updates as elements are removed
+    while (scripts.length > 0) {
+        scripts[0].parentNode.removeChild(scripts[0]);
+    }
+
+    // Iterate over all elements and remove dangerous attributes
+    const allElements = doc.getElementsByTagName('*');
+    for (let i = 0; i < allElements.length; i++) {
+        const el = allElements[i];
+        const attrs = el.attributes;
+        const attrsToRemove = [];
+
+        for (let j = 0; j < attrs.length; j++) {
+            const attr = attrs[j];
+            const name = attr.name.toLowerCase();
+            const value = attr.value.trim().toLowerCase();
+
+            // Remove event handler attributes (onclick, onload, onerror, onmouseover, etc.)
+            if (name.startsWith('on')) {
+                attrsToRemove.push(attr.name);
+                continue;
+            }
+
+            // Remove attributes containing javascript: URLs (href, xlink:href, etc.)
+            if (value.startsWith('javascript:')) {
+                attrsToRemove.push(attr.name);
+                continue;
+            }
+        }
+
+        // Remove collected dangerous attributes
+        for (let k = 0; k < attrsToRemove.length; k++) {
+            el.removeAttribute(attrsToRemove[k]);
+        }
+    }
+
+    // Remove <foreignObject> elements which can contain arbitrary HTML
+    const foreignObjects = doc.getElementsByTagName('foreignObject');
+    while (foreignObjects.length > 0) {
+        foreignObjects[0].parentNode.removeChild(foreignObjects[0]);
+    }
+
+    // Serialize the sanitized DOM back to a string
+    const serializer = new XMLSerializer();
+    return serializer.serializeToString(doc);
+};
+
+module.exports = sanitizeSvg;
